user_stories:
{
  "user_stories": [
    {
      "id": 1,
      "role": "Dreamer",
      "goal": "submit a dream with consent, emotions, and tags to capture manifest content",
      "benefit": "my session starts safely and is ready for interpretation",
      "acceptance_criteria": [
        "I can enter dream text, date/emotions/tags, and confirm privacy/consent before submitting",
        "On submit, a new session is created and saved with my dream narrative as manifest material"
      ]
    },
    {
      "id": 2,
      "role": "Freudian AI Analyst",
      "goal": "generate 5–7 open-ended follow-up questions using free association prompts",
      "benefit": "I can probe latent content and possible wish fulfillment without leading or diagnosing",
      "acceptance_criteria": [
        "The system produces exactly 5–7 questions tailored to the dream and optional prior-session themes",
        "Questions use Freudian vocabulary where relevant (e.g., manifest/latent, condensation, displacement) and include safety-minded, non-diagnostic wording"
      ]
    },
    {
      "id": 3,
      "role": "Dreamer",
      "goal": "answer the follow-up questions sequentially and edit responses",
      "benefit": "my associations are captured clearly for later synthesis",
      "acceptance_criteria": [
        "I can answer each question in order, revise prior answers, and resume if interrupted",
        "My answers are saved to the session alongside the original questions and timestamps"
      ]
    },
    {
      "id": 4,
      "role": "Freudian AI Analyst",
      "goal": "deliver a full analysis separating manifest summary from hypothesized latent meaning",
      "benefit": "the Dreamer receives a coherent, therapeutic interpretation and well-being suggestions",
      "acceptance_criteria": [
        "The analysis includes: manifest content summary, tentative latent-content hypotheses, and at least one wish-fulfillment/unconscious conflict formulation framed as non-factual",
        "It provides reflective prompts and practical well-being suggestions plus clear disclaimers (not therapy/diagnosis) and guidance if distress arises"
      ]
    },
    {
      "id": 5,
      "role": "Dreamer",
      "goal": "review past dream sessions and manage my data",
      "benefit": "I can track recurring themes and control privacy through export or deletion",
      "acceptance_criteria": [
        "I can view a session library showing dreams, questions, answers, and analyses, and open any session to reread details",
        "I can export a session and delete a session, with deletion removing stored content and confirming completion"
      ]
    },
    {
      "id": 6,
      "role": "Administrator",
      "goal": "administer secure session storage, retention, and safety/quality monitoring",
      "benefit": "the product meets privacy, compliance, and tone/safety requirements",
      "acceptance_criteria": [
        "Admin tools allow setting retention/auto-delete policies, handling export/delete requests, and enforcing access control and encryption requirements",
        "Admin can review aggregated safety/quality flags and sampled outputs without exposing unnecessary sensitive content in logs"
      ]
    }
  ]
}
